#version 2
-- Mochi the Corgi: a talking AI dog for any level (a global mod). It talks through Proximity Comms' agents (the host's
-- Koetama asks the host's language model): say "Mochi, sit!" near it. Without them it still obeys plain commands.
-- Files: dog_rig.lua (generated by tools/make_dog.py), dog_anim.lua (poses), dog_brain.lua (the host: the dog's mind,
-- its toys, the agent; more dogs from the spawn menu: spawn.txt, prefab/spawn_mochi.xml), dog_view.lua (every machine:
-- the dogs' models, sounds, E to pet, H for a treat).
#include "dog_rig.lua"
#include "dog_anim.lua"
#include "dog_brain.lua"
#include "dog_view.lua"

function server.init() MochiServerInit() end
function server.tick(dt) MochiServerTick(dt) end
function server.update(dt) MochiServerUpdate(dt) end
function server.postUpdate() MochiServerPostUpdate() end

-- (clients: E on a dog, H anywhere)
function server.mochi_pet(p, k) MochiPet(p, k) end                  -- (k: the dog looked at)
function server.mochi_treat(p) MochiTreat(p) end
function server.mochi_take(p) MochiTakeBall(p) end
function server.mochi_heard(p, vol, x, y, z) MochiHeard(p, vol, x, y, z) end

function client.init() MochiClientInit() end
function client.tick(dt) MochiClientTick(dt) end
function client.render(dt) MochiClientRender(dt) end
function client.draw() MochiClientDraw() end
